   CSS Custom Properties
   ============================================================ */
:root {
  --color-bg: #0d0d0f;
  --color-surface: #16161a;
  --color-surface-2: #1e1e24;
  --color-border: #2a2a32;
  --color-accent: #e8c46a;
  --color-accent-hover: #f0d080;
  --color-accent-dark: #b89040;
  --color-danger: #e85a4f;
  --color-success: #4caf76;
  --color-text: #f0f0f2;
  --color-text-muted: #8e8e9e;
  --color-text-dim: #5a5a6a;
  --color-badge: #e8c46a;

  --font-sans: 'Inter', system-ui, -apple-system, sans-serif;
  --font-serif: 'Georgia', 'Times New Roman', serif;

  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --radius-full: 9999px;

  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.4);
  --shadow-hover: 0 8px 40px rgba(0, 0, 0, 0.6);
  --shadow-focus: 0 0 0 3px rgba(232, 196, 106, 0.5);

  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;

  --header-height: 64px;
}

/* ============================================================
   Reset & Base
   ============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
}

body {
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-sans);
  font-size: 1rem;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

img {
  display: block;
  max-width: 100%;
}

a {
  color: inherit;
  text-decoration: none;
}

ul, ol {
  list-style: none;
}

button {
  cursor: pointer;
  font-family: inherit;
  border: none;
  background: none;
}

/* ============================================================
   Skip Link
   ============================================================ */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  z-index: 9999;
  padding: 0.5rem 1rem;
  background: var(--color-accent);
  color: #000;
  font-weight: 700;
  border-radius: var(--radius-sm);
  transition: top var(--transition-fast);
}

.skip-link:focus {
  top: 1rem;
  outline: 3px solid #000;
  outline-offset: 2px;
}

/* ============================================================
   Focus Styles
   ============================================================ */
:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
}

/* ============================================================
   Header & Nav
   ============================================================ */
.site-header {
  position: sticky;
  top: 0;
  z-index: 100;
  height: var(--header-height);
  background: rgba(13, 13, 15, 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--color-border);
}

.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
  height: 100%;
  display: flex;
  align-items: center;
  gap: 2rem;
}

.site-logo {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 1.25rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--color-text);
  flex-shrink: 0;
}

.site-logo-mark {
  width: 32px;
  height: 32px;
  background: var(--color-accent);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #000;
  font-size: 0.85rem;
  font-weight: 900;
}

.site-logo:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 3px;
  border-radius: var(--radius-sm);
}

.primary-nav {
  flex: 1;
}

.primary-nav-list {
  display: flex;
  gap: 0.25rem;
}

.primary-nav-link {
  display: block;
  padding: 0.4rem 0.75rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background var(--transition-fast);
}

.primary-nav-link:hover,
.primary-nav-link[aria-current="page"] {
  color: var(--color-text);
  background: var(--color-surface-2);
}

.primary-nav-link[aria-current="page"] {
  color: var(--color-accent);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin-left: auto;
}

.header-btn {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem 0.75rem;
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--color-text-muted);
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast), background var(--transition-fast);
}

.header-btn:hover {
  color: var(--color-text);
  background: var(--color-surface-2);
}

.header-btn svg {
  flex-shrink: 0;
}

.cart-btn {
  position: relative;
}

.cart-count {
  position: absolute;
  top: 2px;
  right: 2px;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  background: var(--color-accent);
  color: #000;
  font-size: 0.65rem;
  font-weight: 800;
  border-radius: var(--radius-full);
  display: flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

/* Mobile nav toggle */
.mobile-nav-toggle {
  display: none;
  padding: 0.4rem;
  color: var(--color-text);
  border-radius: var(--radius-sm);
}

/* ============================================================
   Main Layout
   ============================================================ */
.site-main {
  min-height: calc(100vh - var(--header-height));
}

.container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 1.5rem;
}

.section-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 2rem;
}

.section-title {
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--color-text);
}

.section-subtitle {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  margin-top: 0.25rem;
}

.section-link {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-accent);
  display: flex;
  align-items: center;
  gap: 0.25rem;
  white-space: nowrap;
  border-radius: var(--radius-sm);
  padding: 0.25rem 0.5rem;
  transition: color var(--transition-fast), background var(--transition-fast);
}

.section-link:hover {
  color: var(--color-accent-hover);
  background: rgba(232, 196, 106, 0.1);
}

/* ============================================================
   Hero
   ============================================================ */
.hero {
  position: relative;
  overflow: hidden;
  background: var(--color-surface);
  min-height: 540px;
  display: flex;
  align-items: center;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 70% 50%, rgba(232, 196, 106, 0.08) 0%, transparent 60%),
    radial-gradient(ellipse 40% 60% at 85% 30%, rgba(232, 196, 106, 0.05) 0%, transparent 50%),
    linear-gradient(135deg, #0d0d0f 0%, #16161a 100%);
  pointer-events: none;
}

.hero-grid-lines {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(255,255,255,0.025) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.025) 1px, transparent 1px);
  background-size: 60px 60px;
  pointer-events: none;
}

.hero-inner {
  position: relative;
  z-index: 1;
  max-width: 1280px;
  margin: 0 auto;
  padding: 5rem 1.5rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  width: 100%;
}

.hero-eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-accent);
  background: rgba(232, 196, 106, 0.12);
  border: 1px solid rgba(232, 196, 106, 0.25);
  padding: 0.35rem 0.75rem;
  border-radius: var(--radius-full);
  margin-bottom: 1.25rem;
}

.hero-title {
  font-size: clamp(2rem, 5vw, 3.5rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.03em;
  color: var(--color-text);
  margin-bottom: 1.25rem;
}

.hero-title em {
  font-style: normal;
  color: var(--color-accent);
}

.hero-description {
  font-size: 1.0625rem;
  color: var(--color-text-muted);
  line-height: 1.7;
  max-width: 42ch;
  margin-bottom: 2rem;
}

.hero-actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
}

.hero-stats {
  display: flex;
  gap: 2rem;
  margin-top: 2.5rem;
  padding-top: 2rem;
  border-top: 1px solid var(--color-border);
}

.hero-stat-value {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-text);
  letter-spacing: -0.02em;
}

.hero-stat-label {
  font-size: 0.75rem;
  color: var(--color-text-muted);
  margin-top: 0.125rem;
}

.hero-visual {
  position: relative;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.hero-card {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: transform var(--transition-base), box-shadow var(--transition-base);
}

.hero-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-hover);
}

.hero-card-img {
  aspect-ratio: 4/3;
  background: linear-gradient(135deg, #1e1e24, #2a2a34);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
}

.hero-card-body {
  padding: 0.875rem 1rem;
}

.hero-card-name {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-text);
}

.hero-card-price {
  font-size: 0.875rem;
  font-weight: 700;
  color: var(--color-accent);
  margin-top: 0.25rem;
}

.hero-card--large {
  grid-column: span 2;
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.hero-card--large .hero-card-img {
  aspect-ratio: auto;
  min-height: 140px;
  font-size: 4rem;
}

/* ============================================================
   Buttons
   ============================================================ */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.625rem 1.25rem;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: 2px solid transparent;
  transition: background var(--transition-fast), color var(--transition-fast),
              border-color var(--transition-fast), transform var(--transition-fast),
              box-shadow var(--transition-fast);
  line-height: 1;
}

.btn:active {
  transform: scale(0.98);
}

.btn-primary {
  background: var(--color-accent);
  color: #000;
  border-color: var(--color-accent);
}

.btn-primary:hover {
  background: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
}

.btn-primary:focus-visible {
  box-shadow: var(--shadow-focus);
}

.btn-outline {
  background: transparent;
  color: var(--color-text);
  border-color: var(--color-border);
}

.btn-outline:hover {
  border-color: var(--color-text-muted);
  background: var(--color-surface-2);
}

.btn-ghost {
  background: transparent;
  color: var(--color-text-muted);
  border-color: transparent;
  padding: 0.5rem 0.75rem;
  font-size: 0.8125rem;
}

.btn-ghost:hover {
  color: var(--color-text);
  background: var(--color-surface-2);
}

.btn-sm {
  padding: 0.4rem 0.875rem;
  font-size: 0.8125rem;
}

.btn-icon {
  padding: 0.5rem;
  border-radius: var(--radius-sm);
}

/* ============================================================
   Category Strip
   ============================================================ */
.categories {
  padding: 2rem 0;
  border-bottom: 1px solid var(--color-border);
  background: var(--color-surface);
}

.categories-scroll {
  display: flex;
  gap: 0.75rem;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 0.25rem;
}

.categories-scroll::-webkit-scrollbar {
  display: none;
}

.category-chip {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem 1.25rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--color-text-muted);
  white-space: nowrap;
  transition: color var(--transition-fast), border-color var(--transition-fast),
              background var(--transition-fast), transform var(--transition-fast);
  flex-shrink: 0;
  min-width: 90px;
}

.category-chip:hover {
  color: var(--color-text);
  border-color: var(--color-accent);
  background: rgba(232, 196, 106, 0.06);
  transform: translateY(-2px);
}

.category-chip[aria-current="true"] {
  color: var(--color-accent);
  border-color: var(--color-accent);
  background: rgba(232, 196, 106, 0.1);
}

.category-icon {
  font-size: 1.5rem;
}

/* ============================================================
   Product Grid
   ============================================================ */
.featured-products {
  padding: 4rem 0;
}

.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1.25rem;
}

.product-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition-base), box-shadow var(--transition-base),
              transform var(--transition-base);
}

.product-card:hover {
  border-color: rgba(232, 196, 106, 0.3);
  box-shadow: var(--shadow-hover);
  transform: translateY(-4px);
}

.product-img-wrap {
  position: relative;
  aspect-ratio: 1;
  background: var(--color-surface-2);
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}

.product-img-emoji {
  font-size: 4.5rem;
  transition: transform var(--transition-base);
}

.product-card:hover .product-img-emoji {
  transform: scale(1.1);
}

.product-img-actions {
  position: absolute;
  top: 0.75rem;
  right: 0.75rem;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
  opacity: 0;
  transform: translateX(8px);
  transition: opacity var(--transition-base), transform var(--transition-base);
}

.product-card:hover .product-img-actions,
.product-card:focus-within .product-img-actions {
  opacity: 1;
  transform: translateX(0);
}

.product-action-btn {
  width: 36px;
  height: 36px;
  background: rgba(13, 13, 15, 0.9);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background var(--transition-fast), border-color var(--transition-fast),
              color var(--transition-fast);
  backdrop-filter: blur(4px);
}

.product-action-btn:hover {
  background: var(--color-accent);
  border-color: var(--color-accent);
  color: #000;
}

.product-badge {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  padding: 0.2rem 0.55rem;
  font-size: 0.65rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border-radius: var(--radius-full);
}

.badge-new {
  background: #1a3d5c;
  color: #60b8e8;
}

.badge-sale {
  background: rgba(232, 90, 79, 0.2);
  color: #e85a4f;
  border: 1px solid rgba(232, 90, 79, 0.4);
}

.badge-hot {
  background: rgba(255, 140, 50, 0.15);
  color: #ff8c32;
  border: 1px solid rgba(255, 140, 50, 0.3);
}

.badge-bestseller {
  background: rgba(232, 196, 106, 0.15);
  color: var(--color-accent);
  border: 1px solid rgba(232, 196, 106, 0.3);
}

.product-body {
  padding: 1rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-category {
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text-dim);
  margin-bottom: 0.35rem;
}

.product-name {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.35;
  margin-bottom: 0.5rem;
}

.product-name a {
  color: inherit;
  border-radius: var(--radius-sm);
}

.product-name a:hover {
  color: var(--color-accent);
}

.product-name a:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.product-rating {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  margin-bottom: 0.75rem;
}

.stars {
  display: flex;
  gap: 1px;
  color: var(--color-accent);
  font-size: 0.75rem;
}

.stars .star-empty {
  color: var(--color-text-dim);
}

.rating-count {
  font-size: 0.75rem;
  color: var(--color-text-muted);
}

.product-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-top: auto;
}

.product-price {
  display: flex;
  flex-direction: column;
  gap: 0.1rem;
}

.price-current {
  font-size: 1.0625rem;
  font-weight: 700;
  color: var(--color-text);
}

.price-original {
  font-size: 0.75rem;
  color: var(--color-text-dim);
  text-decoration: line-through;
}

.price-discount {
  font-size: 0.75rem;
  color: var(--color-danger);
  font-weight: 600;
}

.add-to-cart-btn {
  flex-shrink: 0;
  width: 36px;
  height: 36px;
  background: var(--color-accent);
  color: #000;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.1rem;
  font-weight: 700;
  transition: background var(--transition-fast), transform var(--transition-fast);
}

.add-to-cart-btn:hover {
  background: var(--color-accent-hover);
  transform: scale(1.05);
}

.add-to-cart-btn:active {
  transform: scale(0.95);
}

.add-to-cart-btn[aria-pressed="true"] {
  background: var(--color-success);
}

/* ============================================================
   Deals Section
   ============================================================ */
.deals {
  padding: 4rem 0;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  border-bottom: 1px solid var(--color-border);
}

.deals-banner {
  background: linear-gradient(135deg, #1a1a08 0%, #16161a 50%, #0d1a0d 100%);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 2rem 2.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  margin-bottom: 2rem;
  position: relative;
  overflow: hidden;
}

.deals-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -10%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(232, 196, 106, 0.07) 0%, transparent 70%);
  pointer-events: none;
}

.deals-banner-text .eyebrow {
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 0.5rem;
}

.deals-banner-text h2 {
  font-size: clamp(1.25rem, 3vw, 2rem);
  font-weight: 800;
  letter-spacing: -0.025em;
  color: var(--color-text);
  margin-bottom: 0.5rem;
}

.deals-banner-text p {
  font-size: 0.9375rem;
  color: var(--color-text-muted);
}

.countdown {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  flex-shrink: 0;
}

.countdown-unit {
  text-align: center;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  padding: 0.625rem 0.875rem;
  min-width: 64px;
}

.countdown-value {
  font-size: 1.75rem;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: var(--color-accent);
  line-height: 1;
  display: block;
}

.countdown-label {
  font-size: 0.6rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-text-dim);
  display: block;
  margin-top: 0.25rem;
}

.countdown-sep {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-text-dim);
  margin-bottom: 0.5rem;
  align-self: center;
}

.deals-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 1.25rem;
}

.deal-card {
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: grid;
  grid-template-columns: 120px 1fr;
  transition: border-color var(--transition-base), box-shadow var(--transition-base),
              transform var(--transition-base);
}

.deal-card:hover {
  border-color: rgba(232, 90, 79, 0.4);
  box-shadow: 0 8px 32px rgba(232, 90, 79, 0.1);
  transform: translateY(-3px);
}

.deal-img {
  background: var(--color-surface);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 3rem;
  border-right: 1px solid var(--color-border);
}

.deal-body {
  padding: 1rem;
}

.deal-discount-badge {
  display: inline-block;
  background: rgba(232, 90, 79, 0.15);
  color: var(--color-danger);
  border: 1px solid rgba(232, 90, 79, 0.3);
  font-size: 0.7rem;
  font-weight: 800;
  padding: 0.15rem 0.45rem;
  border-radius: var(--radius-full);
  margin-bottom: 0.5rem;
  letter-spacing: 0.04em;
}

.deal-name {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
  margin-bottom: 0.375rem;
  line-height: 1.3;
}

.deal-prices {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  margin-bottom: 0.75rem;
}

.deal-price-current {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text);
}

.deal-price-original {
  font-size: 0.8125rem;
  color: var(--color-text-dim);
  text-decoration: line-through;
}

.deal-progress-wrap {
  margin-bottom: 0.75rem;
}

.deal-progress-label {
  font-size: 0.7rem;
  color: var(--color-text-muted);
  margin-bottom: 0.3rem;
  display: flex;
  justify-content: space-between;
}

.deal-progress {
  height: 4px;
  background: var(--color-border);
  border-radius: var(--radius-full);
  overflow: hidden;
}

.deal-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, var(--color-danger), #ff8080);
  border-radius: var(--radius-full);
  transition: width 1s ease;
}

/* ============================================================
   Editorial / Content
   ============================================================ */
.editorial {
  padding: 4rem 0;
}

.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  grid-template-rows: auto auto;
  gap: 1.25rem;
}

.editorial-card {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition-base), box-shadow var(--transition-base),
              transform var(--transition-base);
}

.editorial-card:hover {
  border-color: rgba(232, 196, 106, 0.25);
  box-shadow: var(--shadow-hover);
  transform: translateY(-4px);
}

.editorial-card--featured {
  grid-row: span 2;
}

.editorial-card-img {
  aspect-ratio: 16/9;
  background: linear-gradient(135deg, var(--color-surface-2), #1a1a26);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 5rem;
  flex-shrink: 0;
  position: relative;
  overflow: hidden;
}

.editorial-card--featured .editorial-card-img {
  aspect-ratio: 16/10;
  font-size: 7rem;
}

.editorial-card-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, transparent 50%, rgba(13,13,15,0.8) 100%);
}

.editorial-card-body {
  padding: 1.25rem 1.5rem 1.5rem;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.editorial-tag {
  display: inline-flex;
  align-items: center;
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: 0.75rem;
  gap: 0.4rem;
}

.editorial-tag::before {
  content: '';
  width: 4px;
  height: 14px;
  background: var(--color-accent);
  border-radius: var(--radius-full);
}

.editorial-title {
  font-size: 1.125rem;
  font-weight: 700;
  color: var(--color-text);
  line-height: 1.35;
  margin-bottom: 0.625rem;
  letter-spacing: -0.01em;
}

.editorial-card--featured .editorial-title {
  font-size: clamp(1.25rem, 2.5vw, 1.625rem);
}

.editorial-excerpt {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  line-height: 1.6;
  margin-bottom: 1.25rem;
  flex: 1;
}

.editorial-meta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  font-size: 0.75rem;
  color: var(--color-text-dim);
}

.editorial-meta-author {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.author-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--color-text-muted);
  flex-shrink: 0;
}

.editorial-read-link {
  font-size: 0.8125rem;
  font-weight: 600;
  color: var(--color-accent);
  display: flex;
  align-items: center;
  gap: 0.25rem;
  border-radius: var(--radius-sm);
  padding: 0.25rem 0.5rem;
  transition: color var(--transition-fast), background var(--transition-fast);
  margin-top: 1rem;
  align-self: flex-start;
}

.editorial-read-link:hover {
  color: var(--color-accent-hover);
  background: rgba(232, 196, 106, 0.1);
}

/* ============================================================
   Brand / Trust Strip
   ============================================================ */
.trust-strip {
  padding: 3rem 0;
  border-top: 1px solid var(--color-border);
  background: var(--color-surface);
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2rem;
  text-align: center;
}

.trust-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
}

.trust-icon {
  width: 48px;
  height: 48px;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.375rem;
}

.trust-title {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--color-text);
}

.trust-desc {
  font-size: 0.75rem;
  color: var(--color-text-muted);
  line-height: 1.5;
}

/* ============================================================
   Newsletter
   ============================================================ */
.newsletter {
  padding: 4rem 0;
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
}

.newsletter-inner {
  max-width: 600px;
  margin: 0 auto;
  text-align: center;
}

.newsletter h2 {
  font-size: clamp(1.25rem, 3vw, 1.875rem);
  font-weight: 800;
  letter-spacing: -0.02em;
  color: var(--color-text);
  margin-bottom: 0.75rem;
}

.newsletter p {
  font-size: 0.9375rem;
  color: var(--color-text-muted);
  margin-bottom: 1.75rem;
}

.newsletter-form {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  justify-content: center;
}

.newsletter-input-wrap {
  position: relative;
  flex: 1;
  min-width: 220px;
}

.newsletter-label {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

.newsletter-input {
  width: 100%;
  padding: 0.75rem 1rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  color: var(--color-text);
  font-family: inherit;
  font-size: 0.9375rem;
  transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
}

.newsletter-input::placeholder {
  color: var(--color-text-dim);
}

.newsletter-input:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px rgba(232, 196, 106, 0.2);
}

.newsletter-disclaimer {
  font-size: 0.75rem;
  color: var(--color-text-dim);
  margin-top: 1rem;
}

/* ============================================================
   Footer
   ============================================================ */
.site-footer {
  background: var(--color-surface);
  border-top: 1px solid var(--color-border);
  padding: 3rem 0 1.5rem;
}

.footer-top {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 3rem;
  margin-bottom: 2.5rem;
}

.footer-brand {
  max-width: 280px;
}

.footer-brand .site-logo {
  margin-bottom: 0.875rem;
}

.footer-brand p {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  line-height: 1.65;
  margin-bottom: 1.25rem;
}

.social-links {
  display: flex;
  gap: 0.5rem;
}

.social-link {
  width: 36px;
  height: 36px;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.875rem;
  color: var(--color-text-muted);
  transition: color var(--transition-fast), border-color var(--transition-fast),
              background var(--transition-fast);
}

.social-link:hover {
  color: var(--color-text);
  border-color: var(--color-text-muted);
  background: var(--color-surface-2);
}

.footer-nav-heading {
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-text);
  margin-bottom: 1rem;
}

.footer-nav-list {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.footer-nav-link {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  border-radius: var(--radius-sm);
  padding: 0.125rem 0;
  transition: color var(--transition-fast);
}

.footer-nav-link:hover {
  color: var(--color-text);
}

.footer-bottom {
  border-top: 1px solid var(--color-border);
  padding-top: 1.5rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  font-size: 0.8125rem;
  color: var(--color-text-dim);
}

.footer-bottom-links {
  display: flex;
  gap: 1.5rem;
}

.footer-bottom-link {
  color: var(--color-text-dim);
  border-radius: var(--radius-sm);
  transition: color var(--transition-fast);
}

.footer-bottom-link:hover {
  color: var(--color-text-muted);
}

/* ============================================================
   Toast Notification
   ============================================================ */
.toast-container {
  position: fixed;
  bottom: 1.5rem;
  right: 1.5rem;
  z-index: 9000;
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  pointer-events: none;
}

.toast {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.75rem 1rem;
  background: var(--color-surface-2);
  border: 1px solid var(--color-border);
  border-left: 3px solid var(--color-success);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-card);
  font-size: 0.875rem;
  color: var(--color-text);
  pointer-events: auto;
  animation: toastIn 0.3s ease, toastOut 0.3s ease 2.7s forwards;
  max-width: 320px;
}

.toast-icon {
  font-size: 1rem;
  flex-shrink: 0;
}

@keyframes toastIn {
  from { opacity: 0; transform: translateX(20px); }
  to { opacity: 1; transform: translateX(0); }
}

@keyframes toastOut {
  from { opacity: 1; transform: translateX(0); }
  to { opacity: 0; transform: translateX(20px); }
}

/* ============================================================
   Live Region
   ============================================================ */
.live-region {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
}

/* ============================================================
   Forced Colors
   ============================================================ */
@media (forced-colors: active) {
  .btn-primary {
    background: ButtonText;
    color: ButtonFace;
    border-color: ButtonText;
  }

  .product-card,
  .deal-card,
  .editorial-card {
    border-color: ButtonText;
  }

  .cart-count {
    background: Highlight;
    color: HighlightText;
  }

  .add-to-cart-btn {
    background: ButtonText;
    color: ButtonFace;
  }

  .deal-progress-fill {
    background: Highlight;
  }
}

/* ============================================================
   Responsive
   ============================================================ */
@media (max-width: 1024px) {
  .footer-top {
    grid-template-columns: 1fr 1fr;
  }

  .trust-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .primary-nav { display: none; }

  .mobile-nav-toggle {
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .hero-inner {
    grid-template-columns: 1fr;
    padding: 3rem 1.5rem;
  }

  .hero-visual { display: none; }

  .hero-stats {
    gap: 1.25rem;
  }

  .editorial-grid {
    grid-template-columns: 1fr;
  }

  .editorial-card--featured {
    grid-row: span 1;
  }

  .footer-top {
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
  }

  .footer-brand {
    grid-column: span 2;
    max-width: 100%;
  }

  .deals-banner {
    flex-direction: column;
    text-align: center;
    padding: 1.75rem;
  }

  .footer-bottom {
    flex-direction: column;
    text-align: center;
  }
}

@media (max-width: 480px) {
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 0.75rem;
  }

  .deals-grid {
    grid-template-columns: 1fr;
  }

  .footer-top {
    grid-template-columns: 1fr;
  }

  .footer-brand {
    grid-column: span 1;
  }

  .trust-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 1.25rem;
  }

  .hero-stats {
    flex-wrap: wrap;
    gap: 1rem;
  }

  .countdown {
    flex-wrap: wrap;
    justify-content: center;
  }

  .product-img-emoji {
    font-size: 3rem;
  }
}

/* 320px reflow */
@media (max-width: 320px) {
  .product-grid {
    grid-template-columns: 1fr;
  }
}
