const cart = {
  items: [],

  add(id, name) {
    const existing = this.items.find(i => i.id === id);
    if (existing) {
      existing.qty += 1;
    } else {
      this.items.push({ id, name, qty: 1 });
    }
    this._update();
  },

  get count() {
    return this.items.reduce((s, i) => s + i.qty, 0);
  },

