   ============================================================ */
function showToast(message, icon = '✓') {
  const container = document.getElementById('toast-container');
  if (!container) return;

  const toast = document.createElement('div');
  toast.className = 'toast';
  toast.setAttribute('role', 'status');
  toast.innerHTML = `<span class="toast-icon" aria-hidden="true">${icon}</span><span>${message}</span>`;
  container.appendChild(toast);

  setTimeout(() => {
    toast.remove();
  }, 3000);
}

/* ============================================================
   Add to Cart buttons
   ============================================================ */
function initCartButtons() {
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-add-to-cart]');
    if (!btn) return;

    const id = btn.dataset.addToCart;
    const name = btn.dataset.productName || 'Item';
    const wasAdded = btn.getAttribute('aria-pressed') === 'true';

    cart.add(id, name);
    btn.setAttribute('aria-pressed', 'true');
    btn.setAttribute('aria-label', `${name} added to cart`);

    showToast(`"${name}" added to cart`, '🛒');
    announce(`${name} added to cart. Cart total: ${cart.count} item${cart.count !== 1 ? 's' : ''}.`);

    // Reset visual after short delay
    setTimeout(() => {
      btn.setAttribute('aria-pressed', 'false');
      btn.setAttribute('aria-label', `Add ${name} to cart`);
    }, 2000);
  });
}

/* ============================================================
   Wishlist buttons
   ============================================================ */
function initWishlistButtons() {
  document.addEventListener('click', (e) => {
    const btn = e.target.closest('[data-wishlist]');
    if (!btn) return;

    const name = btn.dataset.productName || 'Item';
    const isWishlisted = btn.getAttribute('aria-pressed') === 'true';
    const newState = !isWishlisted;

    btn.setAttribute('aria-pressed', String(newState));
    btn.setAttribute('aria-label',
      `${newState ? 'Remove' : 'Save'} ${name} ${newState ? 'from' : 'to'} wishlist`
    );

    if (newState) {
      btn.textContent = '♥';
      announce(`${name} saved to wishlist.`);
    } else {
      btn.textContent = '♡';
      announce(`${name} removed from wishlist.`);
    }
  });
}

/* ============================================================
   Countdown Timer
   ============================================================ */
function initCountdown() {
  const hoursEl = document.getElementById('countdown-hours');
  const minsEl = document.getElementById('countdown-mins');
  const secsEl = document.getElementById('countdown-secs');

  if (!hoursEl || !minsEl || !secsEl) return;

  // End time: 11 hours, 43 minutes from now
  const endTime = Date.now() + ((11 * 3600 + 43 * 60 + 22) * 1000);

  function tick() {
    const remaining = Math.max(0, endTime - Date.now());
    const h = Math.floor(remaining / 3600000);
    const m = Math.floor((remaining % 3600000) / 60000);
    const s = Math.floor((remaining % 60000) / 1000);

    hoursEl.textContent = String(h).padStart(2, '0');
    minsEl.textContent = String(m).padStart(2, '0');
    secsEl.textContent = String(s).padStart(2, '0');

    if (remaining > 0) {
      setTimeout(tick, 1000);
    }
  }

  tick();
}

/* ============================================================
   Deal Progress Bars (animate in on scroll)
   ============================================================ */
function initProgressBars() {
  const fills = document.querySelectorAll('[data-progress]');
  if (!fills.length) return;

  const observer = new IntersectionObserver((entries) => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        const el = entry.target;
        el.style.width = el.dataset.progress + '%';
        observer.unobserve(el);
      }
    });
  }, { threshold: 0.2 });

  fills.forEach(el => {
    el.style.width = '0%';
    observer.observe(el);
  });
}

/* ============================================================
   Category Filter
   ============================================================ */
function initCategoryFilter() {
  const chips = document.querySelectorAll('[data-category-filter]');
  chips.forEach(chip => {
    chip.addEventListener('click', () => {
      chips.forEach(c => {
        c.setAttribute('aria-current', 'false');
        c.removeAttribute('aria-current');
      });
      chip.setAttribute('aria-current', 'true');
      announce(`Showing ${chip.dataset.categoryFilter} products`);
    });
  });
}

/* ============================================================
